function [ dx ] = modelo_eq( t_out, x, ws, ks,ts,reg,ns,ne,te,n_s,n_c,ns_a,ts_frozen,points,tal,est,yi,utarg,tstarg,nstarg)
[u] = ver_reg_est1(ws,yi,t_out);
[uref] = ver_reg_est1(ws,yi,t_out);
tau=0.1;
y(3)=( ( x(1)+0.5 )*exp( 25 * x(2)*( x(2)+2 )^(-1) ) );
y(1)=( 0.5 - x(1) - y(3)                             );
y(2)=( -2*( x(2)+0.25 )-u(1)*( x(2) + 0.25 ) + y(3)  );
% y(3)=( ( x(1)+0.5 )*exp( 25 * x(2)*( x(2)+2 )^(-1) ) );
y(4)=( ( x(3)+0.25 )*exp( 25 * x(4)*( x(4)+2 )^(-1) ));

dx(1)=(y(1)                                                     )*tal;
dx(2)=(y(2)                                                     )*tal;
dx(3)=(x(1) - x(3) - tau * y(1) - y(4) + 0.25                   )*tal;
dx(4)=(x(2)-2*x(4)-u(2)*( x(4)+0.25 )-tau*(y(2))+y(4)-0.25      )*tal;
dx(5)=(x(1)^2+x(2)^(2)+x(3)^(2)+x(4)^(2)+0.1*(u(1)^(2)+u(2)^(2)))*tal;
dx=transp(dx);
end                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               
